"""French documentation based on Miblo 0.9 and template packs 0.6."""
from html import escape
from textwrap import dedent
from content.downloads import downloads, VERSION

def code(text, language='shell'):
    return f'<div class="code-block"><div class="code-header"><span>{language}</span><button data-copy aria-label="Copier le code" hidden>Copier</button></div><pre><code>{escape(dedent(text).strip())}</code></pre></div>'

def note(text, label='À savoir'):
    return f'<div class="callout"><span class="callout-marker" aria-hidden="true">[i]</span><div><strong>{label}</strong><p>{text}</p></div></div>'

def table(headers, rows):
    head = ''.join(f'<th scope="col">{h}</th>' for h in headers)
    body = ''.join('<tr>' + ''.join(f'<td>{v}</td>' for v in row) + '</tr>' for row in rows)
    return f'<div class="table-wrap" role="region" aria-label="Tableau : {escape(headers[0], quote=True)}" tabindex="0"><table><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table></div>'

def p(slug, title, group, intro, sections):
    return dict(slug=slug, title=title, group=group, intro=intro, sections=[dict(id=i, title=t, body=b) for i, t, b in sections])

PAGES = [
p('index', 'Documentation', 'Démarrer', 'Installer Miblo, créer une API et gérer ses modèles depuis le terminal.', [
('comprendre', 'Ce que Miblo génère', '<p>Un projet Rust avec <strong>Axum</strong> pour les routes HTTP et <strong>SQLx</strong> pour SQLite ou MySQL. Les sources restent éditables et se lancent avec Cargo.</p>'),
('parcours', 'Démarrer', '<div class="doc-entry-list"><a href="installation.html"><span>01</span><div><strong>Installer Miblo</strong><p>Prérequis et commande d’installation.</p></div><b>→</b></a><a href="premiere-api.html"><span>02</span><div><strong>Créer une API</strong><p>SQLite, User, puis un POST.</p></div><b>→</b></a><a href="interface.html"><span>03</span><div><strong>Utiliser l’interface</strong><p>Panneaux, raccourcis et états.</p></div><b>→</b></a></div>'),
('capacites', 'Trouver une action', '<div class="table-wrap" role="region" aria-label="Tableau : Action" tabindex="0"><table><thead><tr><th scope="col">Action</th><th scope="col">Guide</th></tr></thead><tbody><tr><td>Créer une table et son CRUD</td><td><a href="modeles.html">Modèles et champs</a></td></tr><tr><td>Relier deux modèles</td><td><a href="relations.html">Relations</a></td></tr><tr><td>Ajouter un champ</td><td><a href="migrations.html">Modifier un modèle</a></td></tr><tr><td>Créer une URL</td><td><a href="routes.html">Routes</a></td></tr><tr><td>Envoyer une requête</td><td><a href="tester-les-routes.html">Tester les routes</a></td></tr><tr><td>Configurer ou migrer la base</td><td><a href="bases-de-donnees.html">SQLite et MySQL</a></td></tr><tr><td>Modifier les sources</td><td><a href="architecture.html">Le code généré</a></td></tr><tr><td>Utiliser des scripts</td><td><a href="commandes.html">Référence du CLI</a></td></tr></tbody></table></div>'),
('version', 'Version documentée', f'<p>CLI <strong>{VERSION}</strong>, templates <strong>0.6.0</strong>. La génération concerne Rust. Node.js et OpenAPI ne sont pas disponibles.</p><p>Miblo fournit la structure. Les règles métier, l’authentification et le déploiement restent à développer dans votre projet.</p><p>L’application démarre en anglais. <kbd>Maj+L</kbd> permet de choisir <strong>Français</strong> ou <strong>English</strong>, avec un choix mémorisé. <a href="interface.html#langue">Choisir la langue →</a></p>'),
]),
p('installation', 'Installation', 'Démarrer', 'Installez Miblo avec Cargo ou téléchargez le binaire Windows, macOS ou Linux. Rust, Cargo et rustfmt restent nécessaires pour les API.', [
('prerequis', 'Préparer votre environnement', '<p>Installez <strong>Rust 1.88 ou ultérieur</strong>, Cargo et <code>rustfmt</code> via <a href="https://rustup.rs/">rustup</a>. Le formateur sert à générer et fusionner les sources Rust.</p>' + code('rustup update stable\nrustup component add rustfmt\nrustc --version\ncargo --version') + table(['Système', 'Outils natifs nécessaires'], [('macOS', 'Command Line Tools : <code>xcode-select --install</code>'), ('Linux', 'Compilateur C/C++ et éditeur de liens ; par exemple <code>build-essential</code> sur Debian/Ubuntu.'), ('Windows', 'Visual Studio Build Tools, option « Développement Desktop en C++ », et chaîne Rust MSVC.')]) + '<p>SQLite ne nécessite aucun serveur supplémentaire. Python, Docker et <code>sqlx-cli</code> ne sont pas nécessaires pour utiliser Miblo.</p>'),
('installer', 'Installer', '<div class="code-block"><div class="code-header"><span>shell</span><button data-copy aria-label="Copier le code" hidden>Copier</button></div><pre><code>cargo install miblo --locked\nmiblo --version</code></pre></div><p>Cette commande installe ou met à jour Miblo vers la version documentée. La compilation peut prendre plusieurs minutes. <code>--locked</code> utilise les versions de dépendances testées.</p><details class="doc-details"><summary>Installer depuis un clone du dépôt</summary><div class="code-block"><div class="code-header"><span>shell</span><button data-copy aria-label="Copier le code" hidden>Copier</button></div><pre><code>cargo install --path . --locked</code></pre></div></details>'),
('ouvrir', 'Lancer Miblo', '<div class="code-block"><div class="code-header"><span>shell</span><button data-copy aria-label="Copier le code" hidden>Copier</button></div><pre><code>miblo</code></pre></div><p>La commande ouvre l’interface en anglais par défaut. Pour suivre les menus de ce guide en français, appuyez sur <kbd>Maj+L</kbd>, choisissez <strong>Français</strong> puis <kbd>Entrée</kbd>. Le choix est conservé. Si le dossier courant contient <code>miblo.yaml</code>, le projet est ouvert automatiquement.</p><details class="doc-details"><summary>En ligne de commande</summary><div class="code-block"><div class="code-header"><span>shell</span><button data-copy aria-label="Copier le code" hidden>Copier</button></div><pre><code>miblo ui --project chemin/vers/mon-api</code></pre></div></details><p>Sans terminal interactif, <code>miblo</code> affiche l’aide. Les <a href="commandes.html">sous-commandes</a> restent utilisables dans vos scripts.</p>'),
('distribution', 'Binaires prêts à télécharger', downloads('fr')),
('introuvable', 'Si la commande est introuvable', '<p>Ouvrez un nouveau terminal et vérifiez le dossier des binaires Cargo dans votre <code>PATH</code> : généralement <code>~/.cargo/bin</code> sur Unix et <code>%USERPROFILE%\\.cargo\\bin</code> sur Windows.</p><p>Si la compilation échoue à l’édition de liens, vérifiez les outils natifs du système. Pour les autres erreurs, consultez le <a href="depannage.html">dépannage</a>.</p>'),
]),
p('premiere-api', 'Créer une API REST Rust avec Axum et SQLite', 'Démarrer', 'Créer une API REST avec Rust, Axum et SQLite : générer un modèle User, ses routes CRUD et tester une requête POST avec Miblo.', [
('prerequis', 'Avant de commencer', '<p>Ce tutoriel crée une API locale avec une table <code>users</code>, cinq routes CRUD et une base SQLite. <strong>Miblo CLI</strong> génère les sources Axum et SQLx ; vous pouvez ensuite les modifier librement.</p><p>Il vous faut <strong>Rust 1.88 ou ultérieur</strong>, Cargo, rustfmt et les outils de compilation de votre système. <a href="installation.html#prerequis">Préparer votre environnement →</a> Aucun serveur SQL ni Docker n’est nécessaire pour SQLite. Une connexion Internet est nécessaire au premier téléchargement des templates et des dépendances Rust.</p>' + code('rustup component add rustfmt\ncargo install miblo --version 0.9.1 --locked\nmiblo --version') + '<p>La génération est rapide ; l’installation et la première compilation Rust peuvent prendre plusieurs minutes. Utilisez un dossier neuf et un port 3000 disponible.</p>'),
('projet', '1. Créer le projet', '<div class="code-block"><div class="code-header"><span>shell</span><button data-copy aria-label="Copier le code" hidden>Copier</button></div><pre><code>miblo</code></pre></div><p>Ces étapes suivent les menus français : choisissez <strong>Français</strong> avec <kbd>Maj+L</kbd>, puis <kbd>Entrée</kbd>.</p><ol><li>Appuyez sur <kbd>n</kbd> et saisissez <code>team-api</code>.</li><li>Validez un dossier qui n’existe pas encore, puis le port <code>3000</code>.</li><li>Choisissez <strong>SQLite — fichier local, configuration automatique</strong>.</li><li>Choisissez <strong>GitHub Releases</strong>, puis <strong>Créer le projet</strong>.</li></ol><p>Le projet et le fichier <code>miblo.sqlite</code> sont créés. L’état BDD affiche <strong>Migrations à jour</strong>.</p>'),
('modele', '2. Ajouter User', '<ol><li>Appuyez sur <kbd>a</kbd> et saisissez <code>User</code>.</li><li>Ajoutez <code>name</code>, type <strong>Texte court</strong>, sans option.</li><li>Choisissez <strong>Ajouter un autre champ</strong> : <code>email</code>, type <strong>Texte court</strong>. Cochez <strong>Unique</strong> avec <kbd>Espace</kbd>.</li><li>Choisissez <strong>Terminer et générer</strong>, validez <code>/users</code>, puis <strong>Générer</strong>.</li></ol><p>Miblo crée la table <code>users</code> avec sa clé <code>id</code>, le code Rust et les cinq routes CRUD. L’API étant arrêtée, la migration SQLite est appliquée automatiquement.</p>'),
('requete', '3. Envoyer un POST', '<ol><li>Appuyez sur <kbd>r</kbd> et attendez <strong>API en cours</strong>.</li><li>Passez au panneau Routes avec <kbd>Tab</kbd>, sélectionnez <code>POST /users</code>, puis <kbd>x</kbd>.</li><li>Les champs sont déjà remplis. <kbd>Entrée</kbd> permet de modifier une valeur.</li><li>Sélectionnez <strong>Envoyer la requête</strong> puis <kbd>Entrée</kbd>. La réponse est <strong>HTTP 201</strong>.</li><li>Testez <code>GET /users</code> pour retrouver la ligne créée.</li></ol><p><kbd>s</kbd> arrête l’API. La première compilation prend plus de temps que les lancements suivants.</p>'),
('commandes', 'Le même parcours dans le shell', '<div class="code-block"><div class="code-header"><span>shell</span><button data-copy aria-label="Copier le code" hidden>Copier</button></div><pre><code>miblo new team-api --database sqlite --yes\ncd team-api\nmiblo add User name:string email:string:unique --yes\nmiblo db init\nmiblo run</code></pre></div><p>Ouvrez ensuite <code>miblo</code> dans un second terminal, depuis <code>team-api</code>, pour tester les routes. L’API lancée ailleurs est signalée comme externe.</p>'),
('resultat', 'Les routes et la réponse obtenues', table(['Méthode', 'Route', 'Résultat'], [('POST', '<code>/users</code>', 'Crée un utilisateur : HTTP 201 et son JSON.'), ('GET', '<code>/users</code>', 'Liste paginée : HTTP 200 et un tableau JSON.'), ('GET', '<code>/users/{id}</code>', 'Lit un utilisateur : HTTP 200, ou 404 si absent.'), ('PATCH', '<code>/users/{id}</code>', 'Modifie les champs envoyés : HTTP 200.'), ('DELETE', '<code>/users/{id}</code>', 'Supprime un utilisateur : HTTP 204, sans corps.')]) + '<p>Dans un second terminal, cette commande crée Alice. Les exemples shell utilisent la syntaxe de macOS, Linux ou Git Bash ; depuis PowerShell, vous pouvez utiliser le <a href="tester-les-routes.html">formulaire intégré à Miblo</a>.</p>' + code('curl -i http://127.0.0.1:3000/users \\\n  -H \'Content-Type: application/json\' \\\n  -d \'{"name":"Alice","email":"alice@example.com"}\'') + '<p>Sur une base neuve, le premier utilisateur reçoit l’identifiant <code>1</code>. Réponse HTTP 201 :</p>' + code('{"id":1,"name":"Alice","email":"alice@example.com"}', 'json') + code('curl http://127.0.0.1:3000/users\ncurl http://127.0.0.1:3000/users/1') + '<p>Remplacez <code>1</code> par l’identifiant reçu si votre base contient déjà des lignes. Un deuxième POST avec le même e-mail renvoie <strong>409</strong>, car le champ est unique. L’API reste en cours dans le premier terminal ; <kbd>Ctrl+C</kbd> l’arrête.</p>'),
('fichiers', 'Où modifier le code généré', code('team-api/\n├── Cargo.toml\n├── .env\n├── miblo.yaml\n├── miblo.sqlite\n├── migrations/\n└── src/\n    ├── main.rs\n    ├── database.rs\n    └── resources/user/\n        ├── mod.rs\n        ├── model.rs\n        ├── requests.rs\n        ├── handlers.rs\n        ├── service.rs\n        └── repository.rs', 'arborescence simplifiée') + '<p><code>handlers.rs</code> traite HTTP, <code>service.rs</code> reçoit vos règles métier et <code>repository.rs</code> contient les requêtes SQL. <code>requests.rs</code> décrit les données reçues. <a href="architecture.html">Voir toute l’architecture →</a></p><p>Pour démarrer avec MySQL, utilisez <code>--database mysql</code> dans un nouveau projet et configurez un serveur existant : <a href="bases-de-donnees.html#mysql">configuration MySQL</a>. Cela ne convertit pas une base SQLite existante.</p>'),
('suite', 'Suite du projet', '<p>Continuez avec l’<a href="exemple-equipes.html">exemple User et Group : clé étrangère et route personnalisée</a>.</p><p><kbd>m</kbd> pour <a href="migrations.html">ajouter un champ</a>, <kbd>g</kbd> pour <a href="routes.html">créer une route</a>, <kbd>d</kbd> pour <a href="relations.html#schema">voir le schéma</a> et <kbd>e</kbd> pour ouvrir le code.</p>'),
]),
p('interface', 'Interface et raccourcis', 'Construire', 'Les panneaux, les touches et les états affichés par Miblo.', [
('navigation', 'Naviguer', '<div class="table-wrap" role="region" aria-label="Tableau : Touche" tabindex="0"><table><thead><tr><th scope="col">Touche</th><th scope="col">Action</th></tr></thead><tbody><tr><td><kbd>↑</kbd> <kbd>↓</kbd> ou <kbd>j</kbd> <kbd>k</kbd></td><td>Déplacer la sélection.</td></tr><tr><td><kbd>Tab</kbd> / <kbd>Maj + Tab</kbd></td><td>Changer de panneau.</td></tr><tr><td><kbd>Entrée</kbd></td><td>Valider le choix ou ouvrir la sélection.</td></tr><tr><td><kbd>Échap</kbd></td><td>Fermer le dialogue ou annuler la saisie.</td></tr><tr><td><kbd>Espace</kbd></td><td>Ouvrir le menu Actions ; cocher une option dans un formulaire.</td></tr><tr><td><kbd>?</kbd></td><td>Afficher l’aide.</td></tr></tbody></table></div><p>Les panneaux montrent modèles, fichiers, routes, réponse HTTP et logs. <kbd>d</kbd> remplace les routes par le schéma. <kbd>v</kbd> masque l’aperçu de quatre lignes de code.</p><p>Taille minimale : <strong>70 × 20</strong>. L’aperçu disparaît sous 30 lignes.</p>'),
('raccourcis', 'Les actions principales', table(['Touche', 'Action'], [('<kbd>n</kbd> / <kbd>o</kbd>', 'Créer / ouvrir une API'), ('<kbd>a</kbd>', 'Ajouter modèle, table et CRUD'), ('<kbd>m</kbd>', 'Ajouter champs ou relations à un modèle existant'), ('<kbd>g</kbd>', 'Créer une route'), ('<kbd>r</kbd> / <kbd>s</kbd>', 'Démarrer / arrêter l’API'), ('<kbd>b</kbd>', 'Configurer, initialiser ou migrer la base'), ('<kbd>d</kbd> / <kbd>p</kbd>', 'Voir le schéma / changer sa source'), ('<kbd>x</kbd> / <kbd>Entrée</kbd>', 'Tester la route sélectionnée'), ('<kbd>f</kbd>', 'Requête HTTP libre'), ('<kbd>e</kbd>', 'Ouvrir le code dans votre éditeur'), ('<kbd>c</kbd>', 'Exécuter cargo check'), ('<kbd>u</kbd>', 'Actualiser les templates des futurs ajouts'), ('<kbd>t</kbd> / <kbd>F5</kbd>', 'Changer de thème / rafraîchir'), ('<kbd>Maj+L</kbd>', 'Choisir français ou anglais et mémoriser le choix'), ('<kbd>q</kbd>', 'Quitter')])),
('langue', 'Choisir la langue de Miblo', '<p>Depuis la version 0.9.1, Miblo démarre en <strong>anglais</strong>, quelle que soit la langue du système.</p><ol><li>Appuyez sur <kbd>Maj+L</kbd> (L majuscule), ou ouvrez <kbd>Espace</kbd> → <strong>Language / Langue</strong>.</li><li>Choisissez <strong>Français</strong> ou <strong>English</strong> avec les flèches, puis <kbd>Entrée</kbd>.</li></ol><p><code>:language</code> et <code>:langue</code> ouvrent le même menu. Le changement est immédiat et le choix est conservé au prochain lancement. Le projet reste ouvert et l’API continue à tourner.</p><p>Les menus, formulaires, aides et états changent de langue. Vos fichiers générés, données SQL et anciens logs gardent leur contenu. Les noms de commandes et <code>--help</code> restent en anglais ; les commentaires et le README générés suivent la langue du template.</p><p>Le sélecteur EN / FR du site change uniquement la documentation. Pour Miblo, utilisez le menu de l’application. <a href="configuration.html#preferences">Préférences et variables de langue →</a></p>'),
('commandes', 'La barre de commandes', '<p>Appuyez sur <kbd>:</kbd> pour saisir une commande :</p>' + code(':new    :open chemin/du/projet    :add    :model\n:run    :stop    :db    :migrate    :schema    :templates\n:routes    :route-new    :route    :request    :code\n:check    :test    :doctor    :edit    :refresh    :theme\n:language    :langue    :help    :quit', 'commandes de l’interface') + '<p>Ces commandes internes ne sont pas toutes des sous-commandes du CLI. Pour vos scripts, consultez la <a href="commandes.html">référence CLI</a>.</p>'),
('etats', 'Lire les états', '<div class="table-wrap" role="region" aria-label="Tableau : Couleur" tabindex="0"><table><thead><tr><th scope="col">Couleur</th><th scope="col">API</th><th scope="col">Base de données</th></tr></thead><tbody><tr><td><span class="green">● Vert</span></td><td>Le contrôle HTTP répond.</td><td>Connexion et migrations à jour.</td></tr><tr><td><span class="orange">● Orange</span></td><td>Démarrage ou redémarrage requis.</td><td>Initialisation ou migration à appliquer.</td></tr><tr><td><span class="red">● Rouge</span></td><td>Erreur de processus ou de réponse.</td><td>Connexion impossible ou migration incohérente.</td></tr><tr><td><span class="muted">● Gris</span></td><td>API arrêtée ou aucun projet.</td><td>Vérification en attente ou aucune base.</td></tr></tbody></table></div><p>Les états sont contrôlés environ toutes les trois secondes. Une API externe est identifiée comme telle ; Miblo ne l’arrête pas.</p>'),
('editeur', 'Éditeur, animation et fermeture', '<p><kbd>e</kbd> utilise <code>VISUAL</code>, puis <code>EDITOR</code>, puis vi sur Unix ou notepad sur Windows. Les arguments sont acceptés, par exemple <code>EDITOR="code --wait"</code>. Le terminal est restauré pendant l’édition.</p><p>Une touche passe l’animation bleue ; <code>MIBLO_NO_ANIMATION=1</code> la désactive. Trois thèmes sont proposés pour la session.</p><p>La fermeture normale arrête les processus lancés par Miblo. Terminez les générations, compilations et requêtes en cours avant de quitter : la fermeture est bloquée pendant ces opérations.</p>'),
]),
p('modeles', 'Modèles et champs', 'Construire', 'Un modèle génère une table SQL, des fichiers Rust et cinq routes CRUD.', [
('ajouter', 'Créer un modèle', '<ol><li>Appuyez sur <kbd>a</kbd> et nommez le modèle, par exemple <code>User</code>.</li><li>Nommez un champ, choisissez son type, puis ses options avec <kbd>Espace</kbd>.</li><li>Ajoutez d’autres champs ou une relation depuis <strong>Champs de la ressource</strong>.</li><li>Choisissez <strong>Terminer et générer</strong>, validez le chemin de collection, puis <strong>Générer</strong>.</li></ol><p><code>id</code> est ajouté automatiquement. Utilisez des noms de champs comme <code>first_name</code>. <kbd>Échap</kbd> annule avant génération.</p><details class="doc-details"><summary>En ligne de commande</summary><div class="code-block"><div class="code-header"><span>shell</span><button data-copy aria-label="Copier le code" hidden>Copier</button></div><pre><code>miblo add User name:string email:string:unique --yes\nmiblo add Product title:string price:float active:bool --yes</code></pre></div></details><p><code>--path /members</code> change le chemin de collection. Sans champs ni <code>--yes</code>, le CLI ouvre son assistant.</p>'),
('types', 'Types de champs', table(['Type', 'Rust', 'SQLite', 'MySQL'], [('string', 'String', 'TEXT', 'VARCHAR(255)'), ('text', 'String', 'TEXT', 'TEXT'), ('int', 'i64', 'INTEGER', 'BIGINT'), ('float', 'f64', 'REAL', 'DOUBLE'), ('bool', 'bool', 'INTEGER', 'BOOLEAN')]) + '<p>Un champ facultatif utilise <code>Option&lt;T&gt;</code>. Syntaxe : <code>nom:type?:option</code>, par exemple <code>description:text?</code>.</p>'),
('options', 'Options et champs privés', table(['Option', 'Exemple', 'Comportement'], [('Facultatif', '<code>nickname:string?</code>', 'Accepte NULL.'), ('Unique', '<code>email:string:unique</code>', 'Contrainte d’unicité. Utiliser string plutôt que text pour un texte unique.'), ('Privé', '<code>token:string:private</code>', 'Écriture acceptée ; valeur omise des réponses CRUD.')]) + '<p>Les noms sensibles courants (password, password_hash, secret, token, api_key) deviennent privés via le CLI. Ce filtrage ne chiffre pas les données et ne crée pas d’authentification.</p>'),
('crud', 'Le CRUD produit', table(['Méthode', 'Chemin User', 'Résultat'], [('GET', '/users', 'Liste paginée : limit et offset, maximum 100 par page.'), ('POST', '/users', 'Création : 201.'), ('GET', '/users/{id}', 'Ligne ou 404.'), ('PATCH', '/users/{id}', 'Modification des champs fournis ; champs omis inchangés.'), ('DELETE', '/users/{id}', 'Suppression : 204 ; ligne absente : 404.')]) + '<p>Champs inconnus et types incorrects sont refusés. Unicité : 409. Un PATCH vide, la modification de id et NULL sur un champ obligatoire sont refusés.</p>'),
('preservation', 'Préserver le projet existant', '<p>Un ajout crée les fichiers du nouveau modèle et sa migration sans régénérer les ressources existantes. Les registres, <code>miblo.yaml</code> et <code>.miblo/state.json</code> sont actualisés.</p><p><code>--dry-run</code> montre le plan. Une collision de fichiers ou un conflit dans les registres gérés interrompt l’opération. Pour ajouter un champ, utilisez <a href="migrations.html">miblo edit ou m</a>.</p>'),
]),
p('relations', 'Relations', 'Construire', 'Une clé étrangère relie un champ au id d’un autre modèle.', [
('creer', 'User.group_id → Group.id', '<ol><li>Créez <code>Group</code> avec un champ <code>name</code>.</li><li>Ajoutez <code>User</code> avec <kbd>a</kbd>. Après ses champs, choisissez <strong>Ajouter une relation (clé étrangère)</strong>.</li><li>Sélectionnez <strong>Group → groups.id</strong> et validez le nom proposé <code>group_id</code>.</li><li>Choisissez les options, puis la règle de suppression.</li><li>Terminez et confirmez la génération.</li></ol><p>Miblo génère un entier, un index et une contrainte SQL. Pour User déjà créé, passez par <kbd>m</kbd> → <strong>Ajouter une relation facultative</strong>.</p><details class="doc-details"><summary>En ligne de commande</summary><div class="code-block"><div class="code-header"><span>shell</span><button data-copy aria-label="Copier le code" hidden>Copier</button></div><pre><code>miblo add Group name:string --yes\nmiblo add User name:string &#x27;group_id:int?:ref=Group&#x27; --yes</code></pre></div></details>'),
('regles', 'Choisir la règle de suppression', table(['Règle', 'Effet sur les lignes liées'], [('RESTRICT (défaut)', 'Bloque la suppression de la cible tant qu’elle est référencée.'), ('CASCADE', 'Supprime également les lignes qui la référencent.'), ('SET NULL', 'Conserve les lignes et remplace la référence par NULL ; nécessite un champ facultatif.')]) + code("miblo add Note body:text 'user_id:int?:ref=User:on_delete=set_null' --yes")),
('formes', 'Relations uniques et autoréférences', '<p><code>:unique</code> limite chaque valeur de référence non NULL à une seule ligne. Les autoréférences sont possibles :</p>' + code("miblo add Folder name:string 'parent_id:int?:ref=Folder:on_delete=set_null' --yes") + '<p>Le CRUD expose les identifiants, sans jointures ni objets imbriqués automatiques. Les clés primaires personnalisées/composites et les tables plusieurs-à-plusieurs automatiques ne sont pas générées.</p>'),
('schema', 'Lire le schéma', '<ol><li>Appuyez sur <kbd>d</kbd> pour ouvrir le schéma réel.</li><li>Sélectionnez une table : colonnes, clé primaire, clés étrangères et règles de suppression s’affichent à droite.</li><li><kbd>p</kbd> bascule vers les modèles déclarés. <kbd>F5</kbd> actualise, <kbd>d</kbd> revient aux routes.</li></ol><p>Les tables créées à la main sont aussi visibles. Les tables internes SQLite et SQLx sont masquées. Cette vue affiche la structure ; testez les routes pour consulter les lignes.</p><details class="doc-details"><summary>En ligne de commande</summary><div class="code-block"><div class="code-header"><span>shell</span><button data-copy aria-label="Copier le code" hidden>Copier</button></div><pre><code>miblo db schema --project team-api</code></pre></div></details>'),
]),
]

PAGES += [
p('migrations', 'Modifier un modèle', 'Construire', 'Ajouter des champs ou des relations à une table existante.', [
('modifier', 'Ajouter un champ', '<ol><li>Arrêtez l’API avec <kbd>s</kbd>, puis appuyez sur <kbd>m</kbd>.</li><li>Choisissez le modèle et <strong>Ajouter un champ facultatif</strong>.</li><li>Saisissez <code>nickname</code>, choisissez <strong>Texte court</strong>, puis validez les options.</li><li>Choisissez <strong>Terminer et générer</strong>, relisez le SQL et confirmez.</li></ol><p>Une nouvelle migration <code>ALTER TABLE</code> et les modifications Rust sont générées. Les anciennes lignes recevront <code>NULL</code> dans ce champ après application.</p><details class="doc-details"><summary>En ligne de commande</summary><div class="code-block"><div class="code-header"><span>shell</span><button data-copy aria-label="Copier le code" hidden>Copier</button></div><pre><code>miblo edit User &#x27;nickname:string?&#x27; --dry-run\nmiblo edit User &#x27;nickname:string?&#x27; --yes</code></pre></div></details><p>Pour une relation, choisissez <strong>Ajouter une relation facultative</strong> et le modèle cible. Les <a href="relations.html#regles">règles de suppression</a> s’appliquent aussi.</p>'),
('appliquer', 'Appliquer la migration', '<ol><li>L’état BDD passe à <strong>Mise à jour BDD requise</strong>.</li><li>Appuyez sur <kbd>b</kbd> → <strong>Appliquer les migrations</strong>, puis confirmez.</li><li>Attendez <strong>Migrations à jour</strong> et relancez avec <kbd>r</kbd>.</li></ol><p>Une modification de modèle n’applique pas sa migration automatiquement, y compris sur SQLite. Le lancement de l’API peut aussi appliquer les migrations en attente.</p><details class="doc-details"><summary>En ligne de commande</summary><div class="code-block"><div class="code-header"><span>shell</span><button data-copy aria-label="Copier le code" hidden>Copier</button></div><pre><code>miblo db migrate\nmiblo run</code></pre></div></details><p>Conservez les migrations déjà appliquées sans les modifier.</p>'),
('fusion', 'Vos modifications de code', '<p>Miblo fusionne le code généré avec vos changements. Un conflit interrompt l’opération avant l’écriture. Les handlers et services des modèles actuels restent inchangés lors de l’ajout d’un champ.</p><p>Les fichiers remplacés sont copiés dans <code>.miblo/backups/</code>. Ces copies concernent les sources et métadonnées ; elles ne sauvegardent pas la base.</p>'),
('limites', 'Modifications disponibles', '<div class="table-wrap" role="region" aria-label="Tableau : Automatisé" tabindex="0"><table><thead><tr><th scope="col">Automatisé</th><th scope="col">À écrire dans votre projet</th></tr></thead><tbody><tr><td>Ajouter un champ facultatif, éventuellement unique.</td><td>Renommer, supprimer ou changer le type d’une colonne.</td></tr><tr><td>Ajouter une relation facultative.</td><td>Changer une relation existante ou rendre un champ obligatoire.</td></tr></tbody></table></div><p>Les ajouts conservent les lignes existantes. Miblo ne choisit pas de valeur de remplacement pour elles.</p>'),
]),
p('routes', 'Créer des routes', 'Construire', 'Créer une URL liée au CRUD d’un modèle ou une fonction à compléter.', [
('modele', 'Créer POST /members pour User', '<ol><li>Appuyez sur <kbd>g</kbd> et sélectionnez <strong>User</strong>.</li><li>Choisissez <strong>Créer une ligne</strong>. La méthode POST est déduite.</li><li>Saisissez <code>/members</code>, puis validez ou modifiez le nom de fonction proposé.</li><li>Confirmez avec <strong>Créer les fichiers</strong>.</li><li>Redémarrez l’API avec <kbd>s</kbd>, puis <kbd>r</kbd>, pour charger la route.</li></ol><p>Cette URL utilise le CRUD et les requêtes SQL de User. Elle écrit dans <code>users</code> ; elle ne crée pas de nouvelle table.</p><details class="doc-details"><summary>En ligne de commande</summary><div class="code-block"><div class="code-header"><span>shell</span><button data-copy aria-label="Copier le code" hidden>Copier</button></div><pre><code>miblo route add create_member --resource User --action create --path /members --yes</code></pre></div></details>'),
('actions', 'Actions disponibles', table(['Action CLI', 'Méthode', 'Chemin exemple'], [('list', 'GET', '/members'), ('get', 'GET', '/members/{id}'), ('create', 'POST', '/members'), ('update', 'PATCH', '/members/{id}'), ('delete', 'DELETE', '/members/{id}')]) + '<p>Les actions sur une ligne exigent un seul paramètre {id}. Lister et créer n’en acceptent pas. Plusieurs méthodes peuvent partager un chemin, avec des noms de modules distincts.</p>' + code("miblo route add members --resource User --action list --path /members --yes\nmiblo route add member --resource User --action get --path '/members/{id}' --yes") + note('Une action list sur /users/active reste une liste paginée. Le nom de l’URL ne programme pas un filtre ou une permission.', 'Le chemin ne définit pas le métier')),
('personnalisee', 'Créer une fonction à compléter', '<p>Dans <kbd>g</kbd>, choisissez <strong>Logique personnalisée — sans modèle</strong>, ou un modèle puis <strong>Logique personnalisée — à compléter (501)</strong>. Choisissez ensuite méthode, chemin, nom et corps éventuel.</p><details class="doc-details"><summary>En ligne de commande</summary><div class="code-block"><div class="code-header"><span>shell</span><button data-copy aria-label="Copier le code" hidden>Copier</button></div><pre><code>miblo route add activate_user --method POST --path &#x27;/users/{id}/activate&#x27; --resource User --json-body --yes</code></pre></div></details><p>Les fichiers <code>handlers.rs</code>, <code>requests.rs</code> et <code>service.rs</code> sont créés dans <code>src/resources/custom_routes/activate_user/</code>. La réponse reste <strong>501</strong> jusqu’à l’implémentation de la fonction métier.</p><p>Sélectionnez la route puis <kbd>e</kbd> pour ouvrir son code. La fonction reçoit le pool SQL, les paramètres de chemin, les paramètres de requête et le JSON éventuel. Adaptez leurs types, complétez le traitement, puis redémarrez.</p>'),
('compatibilite', 'Templates, chemins et conflits', '<p>Les actions de modèle nécessitent le pack <strong>0.6.0</strong>. Sur un ancien projet : <kbd>u</kbd> → GitHub Releases, ou <code>miblo template update</code>. Les anciens modèles conservent leur architecture.</p><p>Chemins : /segments/{parametres}, sans query string ni wildcard. Doublons méthode/chemin, collisions connues avec le CRUD ou /health sont refusés. GET réserve HEAD. Vérifiez vous-même les routes branchées hors de Miblo.</p><p><code>--dry-run</code> montre le plan ; <code>--offline</code> réutilise le cache.</p>'),
]),
p('tester-les-routes', 'Tester les routes', 'Construire', 'Choisir une route, modifier les valeurs du formulaire et envoyer.', [
('post', 'Envoyer un POST', '<ol><li>Lancez l’API avec <kbd>r</kbd>. Dans Routes, sélectionnez le POST, puis <kbd>x</kbd>.</li><li>Le formulaire <strong>Préparer la requête</strong> contient les champs du modèle.</li><li>Avec les flèches, choisissez une valeur. <kbd>Entrée</kbd> l’édite.</li><li>Revenez sur <strong>Envoyer la requête</strong> et appuyez sur <kbd>Entrée</kbd>.</li></ol><p>Vous n’avez pas de JSON à saisir. Les champs facultatifs commencent à <code>NULL</code>, les champs privés sont masqués et <code>id</code> est exclu. Les valeurs d’exemple uniques changent à chaque préparation.</p>'),
('patch', 'Modifier avec PATCH', '<div class="table-wrap" role="region" aria-label="Tableau : Commande du formulaire" tabindex="0"><table><thead><tr><th scope="col">Commande du formulaire</th><th scope="col">Effet</th></tr></thead><tbody><tr><td><kbd>Entrée</kbd></td><td>Modifier la valeur sélectionnée.</td></tr><tr><td><kbd>Espace</kbd></td><td>Inclure ou exclure le champ.</td></tr><tr><td><kbd>n</kbd></td><td>Choisir NULL pour un champ facultatif.</td></tr><tr><td><kbd>Début</kbd></td><td>Revenir sur Envoyer la requête.</td></tr><tr><td><kbd>Échap</kbd></td><td>Fermer la saisie ou annuler la requête.</td></tr></tbody></table></div><p>Les champs d’un PATCH commencent exclus : ils gardent leur valeur en base. Incluez ceux à modifier. Un PATCH vide est refusé.</p>'),
('references', 'Choisir une référence existante', '<p>Les clés étrangères proposent jusqu’à 20 lignes obtenues via la collection du modèle cible. Une référence obligatoire est présélectionnée si une ligne existe.</p><p>Sinon, créez d’abord la ligne cible ou saisissez un identifiant existant. Le testeur ne crée pas de ligne liée automatiquement. Une référence facultative peut rester NULL.</p>'),
('libres', 'Requêtes et formulaires libres', '<p><kbd>f</kbd> ouvre une requête libre : GET, POST, PATCH, PUT, DELETE, HEAD ou OPTIONS. Les chemins CRUD connus retrouvent leurs champs. <kbd>+</kbd> ajoute un champ texte, entier, décimal ou booléen ; Suppr le retire.</p><p>Une route personnalisée liée à un modèle utilise ses champs comme suggestion modifiable, pas comme contrat déduit. Les champs du formulaire ne modifient pas vos modèles.</p><p>Les payloads imbriqués, l’inférence des types Rust écrits manuellement et les en-têtes d’authentification personnalisés ne sont pas encore pris en charge. Utilisez un client HTTP externe pour ces besoins.</p>'),
('resultats', 'Lire le résultat', '<p>Miblo affiche code HTTP, durée et réponse formatée. Délai maximal : 10 secondes ; corps affiché : 64 Kio ; redirections non suivies.</p><p>Aucune écriture avant l’action explicite Envoyer. Une suppression sans corps demande confirmation. Échap revient en arrière ou annule.</p>' + table(['Code', 'Interprétation'], [('200 / 201 / 204', 'Lecture ou modification / création / suppression sans contenu.'), ('400 / 422', 'Valeur, structure JSON ou type à vérifier ; 400 pour une référence inexistante.'), ('404', 'Route ou ligne introuvable.'), ('409', 'Contrainte d’unicité (par exemple un e-mail déjà utilisé).'), ('501', 'Fonction personnalisée à compléter.') ])),
]),
p('bases-de-donnees', 'SQLite et MySQL', 'Référence', 'SQLite se configure automatiquement. MySQL nécessite un serveur et une connexion.', [
('sqlite', 'SQLite', '<p>Choisissez SQLite à la création. L’interface prépare <code>.env</code>, crée <code>miblo.sqlite</code> et applique les migrations initiales. Aucun serveur supplémentaire n’est requis.</p><div class="table-wrap" role="region" aria-label="Tableau : Opération dans Miblo" tabindex="0"><table><thead><tr><th scope="col">Opération dans Miblo</th><th scope="col">Migration SQLite</th></tr></thead><tbody><tr><td>Créer le projet</td><td>Appliquée automatiquement.</td></tr><tr><td>Ajouter un modèle, API arrêtée</td><td>Appliquée automatiquement.</td></tr><tr><td>Modifier un modèle avec m</td><td>À appliquer avec b ou au prochain lancement de l’API.</td></tr></tbody></table></div><div class="code-block"><div class="code-header"><span>.env</span><button data-copy aria-label="Copier le code" hidden>Copier</button></div><pre><code>DATABASE_URL=sqlite://miblo.sqlite?mode=rwc</code></pre></div><p>L’API générée crée aussi le fichier manquant et applique les migrations au démarrage.</p>'),
('mysql', 'MySQL', '<ol><li>Démarrez un serveur MySQL, puis choisissez MySQL à la création du projet.</li><li>Renseignez hôte, port, base, utilisateur et mot de passe dans Miblo.</li><li>Validez <strong>Enregistrer la connexion MySQL ?</strong>. Elle est écrite dans <code>.env</code>.</li><li>Dans <kbd>b</kbd>, choisissez <strong>Initialiser la base et ses tables</strong> et confirmez.</li></ol><p>Le compte MySQL doit avoir les droits nécessaires à l’opération. Miblo ne démarre pas le serveur MySQL.</p><details class="doc-details"><summary>Utiliser le compose.yaml fourni</summary><p>Pour le développement local, le projet contient un service MySQL. Utilisez les paramètres de <code>.env.example</code> pour cette connexion.</p><div class="code-block"><div class="code-header"><span>shell</span><button data-copy aria-label="Copier le code" hidden>Copier</button></div><pre><code>docker compose up -d db\n# Une fois MySQL prêt :\nmiblo db init\nmiblo run</code></pre></div></details>'),
('commandes', 'Les actions sur la base', table(['Commande', 'Effet'], [('<code>miblo db check</code>', 'Vérifie la connexion.'), ('<code>miblo db init</code>', 'Initialise la base si nécessaire et applique les migrations.'), ('<code>miblo db migrate</code>', 'Applique les migrations en attente.'), ('<code>miblo db schema</code>', 'Affiche le schéma réel en JSON.')]) + '<p><code>--project PATH</code> permet de travailler depuis un autre dossier. Les mots de passe ne sont pas passés comme arguments.</p>'),
('connexion', 'Configuration et limites', '<p>Les commandes BDD de Miblo lisent d’abord DATABASE_URL dans le .env du projet, puis dans l’environnement si absent du fichier. L’API générée utilise sa configuration d’exécution ; évitez deux valeurs différentes entre fichier et shell.</p><p>Le moteur est fixé à la création. Passer de SQLite à MySQL nécessite une migration de code et de données séparée. Le <a href="relations.html#schema">schéma</a> distingue base réelle et modèles déclarés.</p>'),
]),
p('architecture', 'Le code généré', 'Référence', 'Les fichiers générés et l’endroit où écrire votre code.', [
('arborescence', 'Un dossier par ressource', code('''src/
├── main.rs                  # Démarrage du serveur
├── lib.rs                   # État partagé et assemblage des routes
├── config.rs                # Configuration d’environnement
├── database.rs              # Pool SQL et migrations
├── error.rs                 # Réponses d’erreur
├── patch.rs                 # Champ omis / NULL / valeur
└── resources/
    ├── mod.rs               # Registre géré par Miblo
    └── user/
        ├── mod.rs           # Routes de User
        ├── handlers.rs      # Extraction HTTP et réponses
        ├── model.rs         # Structure des données
        ├── requests.rs      # Requêtes et validation
        ├── service.rs       # Règles métier
        └── repository.rs    # SQL et transactions''', 'arborescence') + '<p>Les migrations sont dans migrations/. Les routes supplémentaires sont dans src/resources/custom_routes/. Le README généré explique la configuration, les fichiers et les requêtes en français.</p>'),
('modifier', 'Où écrire votre logique ?', table(['Besoin', 'Fichier'], [('Règle métier', '<code>service.rs</code>'), ('Validation des requêtes', '<code>requests.rs</code>'), ('Requête SQL', '<code>repository.rs</code>'), ('Extraction et réponse HTTP', '<code>handlers.rs</code>'), ('Routes branchées à la main', '<code>src/lib.rs</code>, hors des registres gérés')]) + '<p>Une écriture suit <strong>handler → service → repository</strong>. Le code est formaté avec rustfmt et accompagné de commentaires ciblés.</p>'),
('autonomie', 'Un projet autonome', code('cargo check\ncargo test\ncargo run') + '<p>L’API fonctionne sans Miblo. Les requêtes SQLx sont exécutées à l’exécution : compiler ne demande pas de base vivante ni de dossier .sqlx. Un lockfile conserve les dépendances.</p><p>Le socle contient des tests de santé et de désérialisation PATCH ainsi que des tests de validation des requêtes dans l’architecture actuelle. Ajoutez les tests propres à votre métier.</p>'),
('registres', 'Les fichiers gérés par Miblo', '<p>Versionnez miblo.yaml et .miblo/state.json avec vos sources. Ils conservent la définition, les versions épinglées et les bases de fusion.</p><p>Les registres src/resources/mod.rs et custom_routes/mod.rs sont gérés par Miblo. Y écrire du métier peut bloquer les ajouts. Personnalisez les fichiers de ressources ou le branchement dans src/lib.rs.</p>'),
]),
p('templates', 'Templates & mode hors ligne', 'Référence', 'Les templates sont téléchargés, vérifiés et mis en cache. Ils restent hors du binaire.', [
('distribution', 'Les packs disponibles', '<p>Les nouveaux projets utilisent le format 3 et les packs <strong>0.6.0</strong>. Le CLI comprend aussi les formats 1 et 2.</p>' + table(['Base', 'Pack'], [('SQLite', '<a href="https://github.com/NaSuRall/miblo_templates/releases/download/v0.6.0/rust-axum-sqlite.tar.gz">rust-axum-sqlite.tar.gz</a>'), ('MySQL', '<a href="https://github.com/NaSuRall/miblo_templates/releases/download/v0.6.0/rust-axum-mysql.tar.gz">rust-axum-mysql.tar.gz</a>')]) + '<p>Chaque archive possède un sidecar .sha256. Le projet épingle version, URL, digest et empreinte. Les templates ne sont pas intégrés au binaire.</p>'),
('cache', 'Utiliser le cache', code('miblo add Note body:text --yes --offline') + '<p>Le mode offline exige un template déjà téléchargé. <code>--cache-dir</code> ou <code>MIBLO_CACHE_DIR</code> choisit le dossier ; sinon XDG_CACHE_HOME, LOCALAPPDATA ou ~/.cache/miblo sont utilisés.</p><p>Le cache de templates est distinct du cache Cargo. Compiler hors ligne exige aussi les dépendances Rust.</p>'),
('mise-a-jour', 'Changer de version', '<p>Appuyez sur <kbd>u</kbd>, choisissez GitHub Releases, un dossier local ou une URL. Confirmez avec <strong>Mettre à jour</strong>.</p><details class="doc-details"><summary>En ligne de commande</summary><div class="code-block"><div class="code-header"><span>shell</span><button data-copy aria-label="Copier le code" hidden>Copier</button></div><pre><code>miblo template update --project team-api</code></pre></div></details><p>Le nouveau pack sert aux futurs modèles et routes. Les modèles existants conservent leur pack ; leurs sources et migrations restent inchangées.</p>'),
('personnaliser', 'Héberger ou développer un pack', code('miblo new team-api --database sqlite \\\n  --template-base-url https://templates.example.com --yes\n\nmiblo new team-api --database sqlite \\\n  --template-url https://templates.example.com/custom/api.tar.gz \\\n  --template-version 0.6.0 --yes') + '<p>Remplacez ces URL d’exemple par votre serveur. Une URL de base est suivie de /v0.6.0/&lt;stack&gt;.tar.gz. <code>--sha256 HEX</code> fournit un digest connu. HTTPS est requis hors loopback de test.</p>' + code('miblo new team-api --database sqlite \\\n  --template-dir ../miblo_templates/rust_sqlite_template_v4 --yes') + '<p>Un pack local contient manifest.json et les fichiers Handlebars. Il doit rester disponible et inchangé. Les releases évitent de maintenir ce dossier local.</p>'),
('integrite', 'Contrôles du téléchargement', '<p>Miblo vérifie le SHA-256 et refuse les archives corrompues, les liens, les fichiers inattendus ou les chemins qui sortent du dossier. Une nouvelle version doit avoir une nouvelle archive.</p><p>Le SHA-256 vérifie le contenu téléchargé ; il ne remplace pas une signature de l’éditeur.</p>'),
]),
p('commandes', 'Référence du CLI', 'Référence', 'Les commandes utilisables dans le shell et dans vos scripts.', [
('global', 'Aide et commandes principales', code('miblo --help\nmiblo --version\nmiblo new --help\nmiblo route add --help') + table(['Commande', 'Usage'], [('<code>miblo</code>', 'Ouvre le TUI dans un terminal interactif.'), ('<code>miblo ui --project PATH</code>', 'Ouvre un projet.'), ('<code>miblo new [NAME]</code>', 'Crée une API.'), ('<code>miblo add [NAME] [FIELD]...</code>', 'Ajoute un modèle.'), ('<code>miblo edit NAME [FIELD]...</code>', 'Ajoute des champs facultatifs.'), ('<code>miblo route add NAME --path PATH</code>', 'Crée une route.'), ('<code>miblo run --project PATH</code>', 'Exécute cargo run.'), ('<code>miblo doctor --project PATH</code>', 'Contrôle métadonnées, registres et prérequis.'), ('<code>miblo db ACTION --project PATH</code>', 'check, init, migrate ou schema.'), ('<code>miblo template update</code>', 'Actualise le template des futurs ajouts.') ])),
('new', 'Créer : miblo new', code('miblo new shop-api --database sqlite --port 3000 \\\n  --resource Product --field title:string --field price:float --yes') + table(['Option', 'Rôle'], [('<code>--output PATH</code>', 'Destination ; un dossier existant est refusé.'), ('<code>--database sqlite|mysql</code>', 'SQLite par défaut en interactif ; MySQL pour --yes sans moteur explicite.'), ('<code>--port PORT</code>', '3000 par défaut.'), ('<code>--resource NAME</code> / <code>--field FIELD</code>', 'Modèle initial et champs répétés.'), ('<code>--config PATH</code>', 'Définition YAML version 1.'), ('<code>--template-dir PATH</code>', 'Pack local ; incompatible avec URL/digest directs.'), ('<code>--template-url URL</code>', 'Archive directe.'), ('<code>--template-base-url URL</code>', 'Serveur de distribution.'), ('<code>--template-version VERSION</code>', 'Version du pack.'), ('<code>--sha256 HEX</code>', 'Digest sans téléchargement du sidecar.'), ('<code>--yes</code> / <code>--dry-run</code>', 'Accepter les choix / voir le plan sans écrire le projet.'), ('<code>--offline</code> / <code>--cache-dir PATH</code>', 'Cache des templates.') ])),
('add-edit', 'Ajouter et faire évoluer', code("miblo add User name:string email:string:unique --yes\nmiblo edit User 'nickname:string?' --yes") + '<p>Les champs sont positionnels ou fournis avec --field répété, jamais les deux à la fois. L’ancien <code>miblo add resource User --field name:string --yes</code> reste accepté.</p><p>Options communes : --project, --yes, --dry-run, --offline, --cache-dir. add accepte aussi --path. edit exige des champs facultatifs et un modèle existant.</p>'),
('route', 'Créer une route', code("miblo route add create_member --resource User --action create --path /members --yes\nmiblo route add activate --method POST --path '/users/{id}/activate' --resource User --json-body --yes") + '<p>--action list|get|create|update|delete exige --resource et déduit la méthode. Sans action, --method et --json-body décrivent le squelette. Autres options : --project, --yes, --dry-run, --offline, --cache-dir.</p>'),
('templates', 'Changer les templates', code('miblo template update --project team-api --dry-run\nmiblo template update --project team-api') + '<p>Options : --template-dir ou --template-url, --template-version, --template-base-url, --project, --dry-run, --offline et --cache-dir. Consultez --help sur votre version avant d’automatiser un nouveau scénario.</p>'),
]),
p('configuration', 'Configuration', 'Référence', 'Les fichiers et variables utilisés par Miblo et par l’API générée.', [
('fichiers', 'Les fichiers importants', table(['Fichier', 'Rôle'], [('<code>miblo.yaml</code>', 'Définition version 1 : projet, modèles, champs et routes.'), ('<code>.miblo/state.json</code>', 'Packs épinglés, empreintes et bases de fusion.'), ('<code>.miblo/backups/</code>', 'Copies des sources remplacées lors des évolutions.'), ('<code>.env</code>', 'Configuration privée d’exécution.'), ('<code>.env.example</code>', 'Exemple partageable.'), ('<code>migrations/</code>', 'Historique SQL versionné.'), ('<code>Cargo.lock</code>', 'Versions des dépendances.')]) + '<p>Versionnez sources, migrations, miblo.yaml et .miblo/state.json. Le .env privé est masqué dans l’explorateur ; .env.example reste visible.</p>'),
('variables', 'Variables d’environnement', table(['Variable', 'Rôle'], [('<code>DATABASE_URL</code>', 'Connexion de l’API ; repli des commandes BDD si le .env ne la définit pas.'), ('<code>SERVER_ADDRESS</code> / <code>SERVER_PORT</code>', 'Écoute du serveur ; rafraîchir après modification.'), ('<code>MIBLO_TEMPLATE_DIR</code>', 'Pack local de développement.'), ('<code>MIBLO_TEMPLATE_BASE_URL</code>', 'Distribution des packs.'), ('<code>MIBLO_CACHE_DIR</code>', 'Cache des templates.'), ('<code>MIBLO_LANGUAGE</code>', 'en ou fr : langue prioritaire au démarrage.'), ('<code>MIBLO_CONFIG_DIR</code>', 'Dossier des préférences utilisateur.'), ('<code>VISUAL</code> / <code>EDITOR</code>', 'Éditeur et arguments.'), ('<code>MIBLO_NO_ANIMATION</code>', 'Désactive l’animation lorsque définie.')]) + '<p>Pour l’adresse surveillée par le TUI, l’environnement prime sur .env, puis sur le projet. Une adresse d’écoute générique est vérifiée via loopback. Évitez les configurations contradictoires.</p>'),
('preferences', 'Préférences utilisateur', '<p>Le choix de langue se trouve dans <code>settings.json</code>, hors de vos projets API :</p><ul><li>macOS : <code>~/Library/Application Support/miblo/settings.json</code></li><li>Linux : <code>$XDG_CONFIG_HOME/miblo/settings.json</code>, ou <code>~/.config/miblo/settings.json</code></li><li>Windows : <code>%APPDATA%\\miblo\\settings.json</code></li></ul><p><code>XDG_CONFIG_HOME</code> est également prioritaire sur macOS. <code>MIBLO_CONFIG_DIR</code> remplace ce dossier sur tous les systèmes.</p><p>Au démarrage, <code>MIBLO_LANGUAGE=en</code> ou <code>MIBLO_LANGUAGE=fr</code> prime sur le choix enregistré. Sans variable ni préférence, Miblo utilise l’anglais. Le menu reste utilisable pendant la session.</p><p>Si l’enregistrement échoue, Miblo signale l’erreur et applique la langue pour la session seulement. Un fichier de préférences invalide ne bloque pas le démarrage et n’est pas écrasé.</p>'),
('definitions', 'Créer depuis une définition', '<p>Un fichier YAML peut décrire un nouveau projet :</p><div class="code-block"><div class="code-header"><span>miblo.yaml</span><button data-copy aria-label="Copier le code" hidden>Copier</button></div><pre><code>schema_version: 1\nname: team-api\nstack: rust-axum-sqlite\nport: 3000\nresources:\n  - name: User\n    path: /users\n    fields:\n      - name: name\n        type: string</code></pre></div><div class="code-block"><div class="code-header"><span>shell</span><button data-copy aria-label="Copier le code" hidden>Copier</button></div><pre><code>miblo new --config chemin/vers/miblo.yaml --yes</code></pre></div><p>Le dossier de destination doit être libre. Modifier ce fichier dans un projet existant ne migre pas la base : utilisez <a href="migrations.html">miblo edit</a> pour ajouter des champs.</p>'),
('compatibilite', 'Versions des projets', '<div class="table-wrap" role="region" aria-label="Tableau : Format" tabindex="0"><table><thead><tr><th scope="col">Format</th><th scope="col">Version</th></tr></thead><tbody><tr><td>Définition miblo.yaml</td><td>schema_version: 1</td></tr><tr><td>Templates actuels</td><td>Pack 0.6.0, format 3</td></tr><tr><td>Formats de templates lus par le CLI</td><td>1, 2 et 3</td></tr></tbody></table></div><p>Un projet peut contenir des modèles issus de plusieurs packs. Les anciens <code>config.yaml</code> ne se convertissent pas automatiquement. Le changement de moteur, les renommages et les suppressions demandent une migration manuelle.</p>'),
]),
p('depannage', 'Dépannage', 'Aide et contribution', 'Les erreurs courantes et les actions pour les résoudre.', [
('doctor', 'Faire un diagnostic', '<div class="code-block"><div class="code-header"><span>shell</span><button data-copy aria-label="Copier le code" hidden>Copier</button></div><pre><code>miblo doctor --project team-api\nmiblo db check --project team-api</code></pre></div><p><code>doctor</code> vérifie le projet et ses prérequis. <code>db check</code> vérifie la connexion. Consultez le panneau Logs pour le détail d’une erreur.</p>'),
('template-404', 'Template indisponible ou erreur 404', '<p>Vérifiez la version, la source et l’accès aux <a href="https://github.com/NaSuRall/miblo_templates/releases">releases</a>. Pour une URL personnalisée, archive et sidecar .sha256 doivent exister.</p><p>L’interface propose de changer de source ou réessayer sans perdre nom, destination et port. Un échec de téléchargement ne crée pas le projet.</p>'),
('template-change', 'Template changed since project creation', '<p>Le pack local épinglé a changé ou est indisponible. Restaurez son contenu exact pour les modèles qui en dépendent. Pour les prochains ajouts, choisissez un pack publié via u ou :</p>' + code('miblo template update --project team-api') + '<p>Cette mise à jour ne réécrit pas les anciens modèles ni leur historique. Ne supprimez pas les métadonnées pour contourner le contrôle.</p>'),
('route-501', 'La route renvoie 501', '<p>La route utilise <strong>Logique personnalisée</strong>. Sélectionnez-la, appuyez sur <kbd>e</kbd> et complétez <code>service.rs</code>, puis redémarrez.</p><p>Pour utiliser directement le SQL d’un modèle, créez une route en choisissant ce modèle <strong>et une action CRUD</strong> : lister, consulter, créer, modifier ou supprimer.</p>'),
('bdd-orange', 'La base est orange ou rouge', '<div class="table-wrap" role="region" aria-label="Tableau : État affiché" tabindex="0"><table><thead><tr><th scope="col">État affiché</th><th scope="col">Action</th></tr></thead><tbody><tr><td>Mise à jour BDD requise</td><td>Arrêter l’API, puis b → Appliquer les migrations.</td></tr><tr><td>Base à initialiser</td><td>b → Initialiser la base et ses tables.</td></tr><tr><td>Base inaccessible</td><td>Vérifier la connexion ; pour MySQL, le serveur et ses accès.</td></tr><tr><td>Migration incohérente</td><td>Restaurer la migration déjà appliquée, puis créer une nouvelle migration pour le changement.</td></tr></tbody></table></div>'),
('conflits', 'Conflit ou opération interrompue', '<p>Un fichier déjà présent, un registre modifié ou du code incompatible avec la fusion bloque la génération. Résolvez les fichiers indiqués avant de relancer. Placez les branchements manuels dans src/lib.rs.</p><p>Une interruption peut laisser .miblo/operation.lock et des écritures partielles. Vérifiez qu’aucune opération ne tourne, inspectez le diff et restaurez un état cohérent, puis retirez le verrou obsolète. Les écritures multifichiers ne sont pas une transaction atomique.</p>'),
('langue', 'La langue change au redémarrage', '<p>Choisissez la langue avec <kbd>Maj+L</kbd> puis <kbd>Entrée</kbd>. Si <code>MIBLO_LANGUAGE</code> est définie dans votre shell, elle prime au prochain lancement : retirez cette variable pour utiliser le choix enregistré.</p><p>Si Miblo indique que la préférence ne peut pas être enregistrée, vérifiez les droits du <a href="configuration.html#preferences">dossier de préférences</a> et la validité de <code>settings.json</code>. La session courante reste utilisable.</p>'),
('compiler', 'Compilation, port ou commande introuvable', '<p>Installez rustfmt avec <code>rustup component add rustfmt</code>. Pour l’édition de liens, vérifiez les outils C/C++. Pour un port occupé, changez SERVER_PORT, rafraîchissez avec F5 puis redémarrez.</p><p>Vérifiez le PATH Cargo pour une commande introuvable. Dans une issue, fournissez version, système, commande et erreur, sans votre .env privé.</p>'),
]),
p('contribuer', 'Contribuer', 'Aide et contribution', 'Le CLI, les templates et ce site sont open source sous licence MIT.', [
('depots', 'Les dépôts', '<ul><li><a href="https://github.com/NaSuRall/Miblo">Miblo</a> : CLI, TUI, génération et gestion des projets.</li><li><a href="https://github.com/NaSuRall/miblo_templates">miblo_templates</a> : packs Handlebars et archives publiées.</li><li><a href="https://github.com/NaSuRall/miblo_site">miblo_site</a> : ce site et sa documentation.</li></ul><p>Signalez une erreur, proposez une amélioration ou contribuez aux sources via GitHub.</p>'),
('checks', 'Vérifier le CLI', '<div class="code-block"><div class="code-header"><span>shell</span><button data-copy aria-label="Copier le code" hidden>Copier</button></div><pre><code>cargo fmt --check\ncargo clippy --locked --all-targets -- -D warnings\ncargo test --locked</code></pre></div><p>Les scripts du dépôt couvrent aussi l’installation, la génération, les migrations, le CRUD SQLite/MySQL et le TUI. Les dépendances de test sont listées dans <code>scripts/requirements-test.txt</code>.</p>'),
('templates', 'Tester une API générée', '<p>Avec CLI et templates dans des dossiers voisins :</p>' + code('cargo build --locked\npython3 scripts/smoke_sqlite.py \\\n  --miblo target/debug/miblo \\\n  --templates ../miblo_templates/rust_sqlite_template_v4 \\\n  --target-dir target/sqlite-smoke') + '<p>Ces tests créent leurs projets et données temporaires. Consultez le README de la branche de développement pour les parcours MySQL, TUI et installation et leurs dépendances.</p>'),
('beta', 'Avant une publication', '<p>Vérifiez l’installation, la génération depuis les releases, les migrations et la préservation des modifications manuelles. Le test automatisé du TUI tourne sur Unix ; vérifiez également le terminal Windows.</p><p>Le CLI, les templates et le site se publient séparément. Les instructions de chaque dépôt décrivent leurs contrôles.</p>'),
]),
]
